<script setup>import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {findProduct} from '../data/products';import {useCart} from '../stores/cart';const route=useRoute(),cart=useCart(),quantity=ref(1),product=computed(()=>findProduct(String(route.params.slug)));</script>
<template><section v-if="product" class="detail"><div class="art" :class="product.tone"><i>{{String(product.id).padStart(2,'0')}}</i><b>{{product.symbol}}</b><small>{{product.badge}}</small></div><div class="copy"><RouterLink to="/products">← Back to collection</RouterLink><span>{{product.category}}</span><h1>{{product.name}}</h1><p>{{product.description}}</p><strong class="price">${{product.price}}</strong><div class="buy"><select v-model.number="quantity"><option v-for="n in 5" :key="n" :value="n">{{n}}</option></select><button @click="cart.add(product,quantity)">Add to bag</button></div></div></section><section v-else class="missing"><h1>Object not found.</h1><RouterLink class="solid-button" to="/products">Return</RouterLink></section></template>
<style scoped>.detail{padding:74px 7vw;display:grid;grid-template-columns:1fr 1fr;gap:72px;align-items:center}.art{position:relative;min-height:610px;display:grid;place-items:center;border-radius:38px}.art:after{content:'';position:absolute;width:380px;height:380px;border:1px solid rgba(31,35,31,.2);border-radius:50%}.peach{background:#f2c5aa}.mint{background:#b8d8ca}.sky{background:#bdd7e7}.lilac{background:#d4c6dd}.sand{background:#dfcfaa}.rose{background:#e8bcc3}.blue{background:#aebfd8}.green{background:#b9cca5}.art b{z-index:2;font:400 185px Georgia}.art i{position:absolute;top:24px;left:26px;font:italic 38px Georgia}.art small{position:absolute;right:24px;bottom:24px;padding:8px 13px;border-radius:999px;background:rgba(255,253,248,.75);font-weight:900}.copy>a{color:var(--muted)}.copy>span{display:block;margin-top:52px;color:var(--coral-dark);font-size:10px;font-weight:900;letter-spacing:.18em;text-transform:uppercase}h1{margin:10px 0 18px;font:400 clamp(56px,7vw,92px)/.9 Georgia;letter-spacing:-.05em}.copy p{max-width:620px;color:var(--muted);font-size:18px;line-height:1.75}.price{display:block;font-size:30px}.buy{margin-top:27px;display:flex;gap:12px}.buy select{padding:14px;border:1px solid var(--line);border-radius:999px;background:transparent}.buy button{flex:1;border:0;border-radius:999px;background:var(--ink);color:white;font-weight:900}.missing{padding:120px;text-align:center}@media(max-width:850px){.detail{grid-template-columns:1fr;padding-inline:20px}.art{min-height:470px}}</style>
